window.kbPageData["views/entry/k-06be6ba4390f814c"] = {"key":"entry/k-06be6ba4390f814c","state":{"route":"entry/k-06be6ba4390f814c"},"node":{"id":"k-06be6ba4390f814c","mode":"k","title":"重大战略任务","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["公共管理","经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"二是突出做强国内大循环①。在外部环境复杂严峻的情况下，必须坚持扩大内需这个战\n略基点②。《纲要（草案）》着眼增强国内大循环内生动力和可靠性，坚持惠民生和促消费、\n投资于物和投资于人紧密结合，大力提振消费，促进居民消费率明显提高，扩大有效投资。\n着眼充分释放我国超大规模市场红利，纵深推进全国统一大市场…","sources":[{"id":"12e90c0b38637c9e","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"二是突出做强国内大循环①。在外部环境复杂严峻的情况下，必须坚持扩大内需这个战\n略基点②。《纲要（草案）》着眼增强国内大循环内生动力和可靠性，坚持惠民生和促消费、\n投资于物和投资于人紧密结合，大力提振消费，促进居民消费率明显提高，扩大有效投资。\n着眼充分释放我国超大规模市场红利，纵深推进全国统一大市场建设，破除地方保护和市\n场分割。着眼增强高质量发展动力，充分激发各类经营主体活力，加快完善要素市场化配置\n体制机制。着眼畅通国内国际双循环，统筹用好全球要素和市场资源。","source":{"doc":"6cbfb01fe723bba64b75","first":17,"last":17,"page":17,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"f5190da3839df905","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"三是突出推进全体人民共同富裕①。中国式现代化是全体人民共同富裕的现代化②。《纲\n要（草案）》着眼建设生育友好型社会，健全人口服务体系；办好人民满意的教育，劳动\n年龄人口平均受教育年限提高到 11.7 年；加快建设健康中国和体育强国，人均预期寿命提\n高到 80 岁；积极应对人口老龄化，养老机构护理型床位占比提高到 73%；促进高质量充分\n就业，完善收入分配制度③，健全社会保障体系④。着眼缩小区域差距和城乡差别，加快农\n业农村现代化，持续巩固拓展脱贫攻坚成果，优化重大生产力布局，深入推进以人为本的新\n型城镇化。着眼促进人民精神生活共同富裕，弘扬和践行社会主义核心价值观⑤，大力繁荣\n文化事业，加快发展文化产业，提升中华文明传播力影响力。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":18,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"7beaf32bdc2cab80","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"四是突出统筹发展和安全。安全是发展的前提，发展是安全的保障。《纲要（草案）》\n贯彻总体国家安全观①，着眼推进国家安全体系和能力现代化提出多项任务举措。增强粮食、\n能源资源等供给保障能力，粮食综合生产能力②达到 1.45 万亿斤左右，能源综合生产能力③\n达到 58 亿吨标准煤。统筹推进房地产、地方政府债务、地方中小金融机构等风险有序化解。\n提高公共安全治理水平，有效维护社会安全稳定。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"b2f01ec486c36c42","label":"重大战略任务","topic":"年度政府工作","category":"时政","text":"（二）重大战略任务\n《纲要（草案）》分领域阐述了“十五五”发展的重大战略任务，突出体现四个方面。\n一是突出推动高质量发展。发展新质生产力①是高质量发展的内在要求。《纲要（草案）》\n强调科技创新的引领作用，着眼巩固壮大实体经济②根基，构建以先进制造业为骨干的现代\n化产业体系③。着眼高水平科技自立自强④，加强原始创新和关键核心技术攻关，深入推进\n数字中国建设⑤，数字经济核心产业增加值占国内生产总值比重达到 12.5%。着眼建设美丽\n中国，持续深入推进污染防治攻坚和生态系统优化，加快形成绿色生产生活方式，确保碳\n达峰目标⑥如期实现。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":16,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-06be6ba4390f814c":[]}};
